/* Selectable research-plan template. Uses existing routes; does not run analyses. */
'use strict';
(()=>{
  const LANGS=['zh','en','fr','es','eu'];
  const COPY={
    label:['研究方案模板','Research-plan template','Modèle de plan de recherche','Plantilla de plan de investigación','Ikerketa-planaren txantiloia'],
    title:['酵母群体表达噪音与遗传调控','Expression noise and genetic regulation across yeast populations','Bruit d’expression et régulation génétique dans les populations de levures','Ruido de expresión y regulación genética en poblaciones de levadura','Adierazpen-zarata eta erregulazio genetikoa legamia-populazioetan'],
    intro:['按研究目标组合现有路线，先复现分子证据与表达分布，再选择遗传分析和机制扩展。','Combine existing routes by research aim: establish molecular evidence and expression distributions, then select genetic and mechanistic analyses.','Combinez les axes existants selon vos objectifs : établir les preuves moléculaires et les distributions d’expression, puis choisir les analyses génétiques et mécanistiques.','Combine las líneas existentes según su objetivo: establecer evidencia molecular y distribuciones de expresión, y después elegir análisis genéticos y mecanísticos.','Konbinatu dauden ildoak ikerketa-helburuaren arabera: ezarri ebidentzia molekularra eta adierazpen-banaketak, eta hautatu analisi genetikoak eta mekanistikoak.'],
    foundation:['基础复现','Foundational reproduction','Reproduction des analyses de base','Reproducción de análisis básicos','Oinarrizko analisien erreprodukzioa'],
    foundationHelp:['检查原始分子、QC和参考偏差，建立可解释的注释及均值—噪音基线。','Audit raw molecules, QC and reference bias; establish interpretable annotations and a mean–noise baseline.','Examiner les molécules brutes, le contrôle qualité et le biais de référence; établir des annotations interprétables et une base moyenne–bruit.','Auditar moléculas originales, control de calidad y sesgo de referencia; establecer anotaciones interpretables y una base media–ruido.','Aztertu jatorrizko molekulak, kalitate-kontrola eta erreferentzia-alborapena; ezarri anotazio interpretagarriak eta batezbesteko–zarata oinarria.'],
    progression:['预期推进','Next-stage research','Étapes de recherche suivantes','Siguientes etapas de investigación','Ikerketaren hurrengo urratsak'],
    progressionHelp:['分解状态与噪音，评估功效，再连接菌株遗传背景、细胞状态和群体历史。','Separate state and noise, assess power, then connect strain genetics, cell states and population history.','Distinguer état et bruit, évaluer la puissance, puis relier génétique des souches, états cellulaires et histoire des populations.','Separar estado y ruido, evaluar potencia y conectar genética de cepas, estados celulares e historia poblacional.','Bereizi egoera eta zarata, ebaluatu potentzia, eta lotu anduien genetika, zelula-egoerak eta populazio-historia.'],
    mechanism:['机制扩展','Mechanistic extensions','Extensions mécanistiques','Extensiones mecanísticas','Hedapen mekanistikoak'],
    mechanismHelp:['从分布尾部、协同程序和调控网络，延伸到动力学、遗传共享与模拟扰动。','Extend distribution tails, coordinated programs and regulatory networks into dynamics, shared genetics and simulated perturbations.','Étendre l’étude des queues de distribution, programmes coordonnés et réseaux vers la dynamique, la génétique partagée et les perturbations simulées.','Ampliar colas de distribución, programas coordinados y redes hacia dinámica, genética compartida y perturbaciones simuladas.','Hedatu banaketa-isatsen, programa koordinatuen eta sareen azterketa dinamikara, genetika partekatura eta perturbazio simulatuetara.'],
    all:['全选本组','Select group','Sélectionner le groupe','Seleccionar grupo','Hautatu taldea'],clear:['清除本组','Clear group','Effacer le groupe','Vaciar grupo','Garbitu taldea'],detail:['查看详情','View details','Voir les détails','Ver detalles','Ikusi xehetasunak'],
    selected:['已选路线','Selected routes','Axes sélectionnés','Líneas seleccionadas','Hautatutako ildoak'],add:['加入选中路线并检查方案','Add selected routes and review plan','Ajouter les axes et vérifier le plan','Añadir líneas y revisar el plan','Gehitu ildoak eta berrikusi plana'],
    note:["将勾选路线合并到现有方案，再核对数据要求。已有项目保留。", "Merge checked routes into your plan, then review data requirements. Existing projects are retained.", "Ajoutez les axes cochés au plan, puis vérifiez les données requises. Les projets existants sont conservés.", "Añada las líneas marcadas al plan y revise los datos necesarios. Se conservan los proyectos existentes.", "Gehitu markatutako ildoak planari eta berrikusi datu-eskakizunak. Lehendik dauden proiektuak mantentzen dira."],
    empty:['请选择至少一条研究路线。','Select at least one research route.','Sélectionnez au moins un axe.','Seleccione al menos una línea.','Hautatu gutxienez ikerketa-ildo bat.'],
    failure:['未能加入方案，请重试。当前勾选已保留。','Could not add routes. Please retry; your selections are retained.','Impossible d’ajouter les axes. Réessayez; vos sélections sont conservées.','No se pudieron añadir las líneas. Reinténtelo; se conservan sus selecciones.','Ezin izan dira ildoak gehitu. Saiatu berriro; hautapenak gordeta daude.']
  };
  const GROUPS=[
    {id:'foundation',ids:['audit_raw','qc_multiverse','reference_bias','annotation_transfer','marker_panel','mean_noise','noise_cycle']},
    {id:'progression',ids:['noise_components','noise_power','noise_qtl','genotype_state','evolution_context']},
    {id:'mechanism',ids:['distribution_shapes','program_variability','grn_rewiring','velocity_feasibility','trajectory_structure','splice_evidence','virtual_perturbation','shared_genetic_architecture','mechanistic_noise_benchmark']}
  ];
  const selected=new Set(GROUPS[0].ids),A=()=>window.YV_APP,B=()=>window.YV_BUILDER;
  const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const language=()=>LANGS.includes(A()?.prefs?.().language)?A().prefs().language:'en';
  const T=key=>COPY[key]?.[LANGS.indexOf(language())]||COPY[key]?.[1]||key;
  const projects=()=>A()?.data?.()?.projects?.projects||[],lookup=()=>new Map(projects().map(p=>[p.id,p]));
  const chosen=()=>{const map=lookup();return GROUPS.flatMap(g=>g.ids).filter(id=>selected.has(id)&&map.has(id));};
  function title(record){const value=A()?.tx?.(record.title)||record.title;return language()!=='zh'&&/[\u3400-\u9fff]/u.test(value)?record.titleEn||record.id:value;}
  function groupHTML(group,map){const available=group.ids.filter(id=>map.has(id));return `<article class="ps25-card ps25-${group.id}"><header><span class="ps25-number" aria-hidden="true">${GROUPS.indexOf(group)+1}</span><h3>${E(T(group.id))}</h3><p>${E(T(group.id+'Help'))}</p></header><div class="ps25-group-actions"><button type="button" data-ps25-group="${group.id}" data-ps25-mode="all">${E(T('all'))}</button><button type="button" data-ps25-group="${group.id}" data-ps25-mode="clear">${E(T('clear'))}</button><span data-ps25-count="${group.id}">${available.filter(id=>selected.has(id)).length} / ${available.length}</span></div><ul>${available.map(id=>{const p=map.get(id);return `<li><label><input type="checkbox" data-ps25-route="${E(id)}" ${selected.has(id)?'checked':''}><span>${E(title(p))}</span></label><button type="button" data-ps25-detail="${E(id)}" aria-label="${E(T('detail')+' · '+title(p))}">${E(T('detail'))}</button></li>`;}).join('')}</ul></article>`;}
  function panel(){const map=lookup();if(!map.size)return '';return `<section class="ps25-study" id="population-study-v25f" aria-labelledby="ps25-title"><header class="ps25-heading"><span class="ps25-eyebrow">${E(T('label'))}</span><h2 id="ps25-title">${E(T('title'))}</h2><p>${E(T('intro'))}</p></header><div class="ps25-grid">${GROUPS.map(g=>groupHTML(g,map)).join('')}</div><footer class="ps25-footer"><div><p class="ps25-status" role="status" aria-live="polite" aria-atomic="true">${E(T('selected'))}: <strong data-ps25-total>${chosen().length}</strong></p><p class="ps25-note">${E(T('note'))}</p><p data-ps25-error role="alert" hidden></p></div><button type="button" class="ps25-submit" data-ps25-add ${!chosen().length||!B()?.setProjects?'disabled':''}>${E(T('add'))}</button></footer></section>`;}
  function refresh(){const root=document.getElementById('population-study-v25f');if(!root)return;const map=lookup();root.querySelectorAll('[data-ps25-route]').forEach(input=>{input.checked=selected.has(input.dataset.ps25Route);});root.querySelectorAll('[data-ps25-count]').forEach(el=>{const group=GROUPS.find(g=>g.id===el.dataset.ps25Count),ids=group.ids.filter(id=>map.has(id));el.textContent=`${ids.filter(id=>selected.has(id)).length} / ${ids.length}`;});const total=root.querySelector('[data-ps25-total]');if(total)total.textContent=chosen().length;const add=root.querySelector('[data-ps25-add]');if(add)add.disabled=!chosen().length||!B()?.setProjects;const error=root.querySelector('[data-ps25-error]');if(error){error.hidden=true;error.textContent='';}}
  document.addEventListener('change',event=>{const input=event.target;if(!input?.matches?.('[data-ps25-route]')||!lookup().has(input.dataset.ps25Route))return;if(input.checked)selected.add(input.dataset.ps25Route);else selected.delete(input.dataset.ps25Route);refresh();});
  document.addEventListener('click',event=>{const button=event.target.closest?.('[data-ps25-group],[data-ps25-detail],[data-ps25-add]');if(!button)return;if(button.dataset.ps25Group){const group=GROUPS.find(g=>g.id===button.dataset.ps25Group);if(!group)return;const map=lookup();for(const id of group.ids)if(map.has(id)){if(button.dataset.ps25Mode==='all')selected.add(id);else selected.delete(id);}refresh();return;}if(button.dataset.ps25Detail){if(lookup().has(button.dataset.ps25Detail))A()?.openRecord?.('project',button.dataset.ps25Detail);return;}if(button.hasAttribute('data-ps25-add')){if(!chosen().length||!B()?.setProjects)return;try{B().setProjects([...new Set([...(B().getPlan().projects||[]),...chosen()])]);location.hash='#workbench?stage=scope';}catch{const error=document.querySelector('#population-study-v25f [data-ps25-error]');if(error){error.textContent=T('failure');error.hidden=false;}}}});
  window.YV_POPULATION_STUDY={panel,getSelection:()=>chosen()};
})();
